from ui import theme

def probe(label, options):
    root = tk.Tk()
    for pat, val in options:
        try:
            root.option_add(pat, val)
        except Exception as e:
            print(label, "option_add fail", pat, e)
    try:
        tk.Menu(root)
        print(label, "-> menu ok")
    except Exception as e:
        print(label, "-> menu FAIL:", e)
    root.destroy()

probe("bg only", [("*Background", theme.COLORS["bg"])])
probe("fg only", [("*Foreground", theme.COLORS["fg"])])
probe("font only", [("*Font", "Segoe UI 9")])
probe("font+size", [("*Font", "Segoe UI 9")])
probe("all three", [("*Background", theme.COLORS["bg"]), ("*Foreground", theme.COLORS["fg"]), ("*Font", "Segoe UI 9")])
probe("font helvetica", [("*Font", "Helvetica 9")])
", "file_path": "_dbg_menu5.py"}

