{"file_path": "ui/app.py", "new_string": "    def refresh(self) -> None:
        """Перерисовать экран и чек из платы. Дёшево, никогда не бросает.

        Хост (``main.py``) вызывает этот метод каждые ~50 мс. Если плата ещё не
        прошла ``boot()`` (все поля нули/пусто) или её методы бросают исключения,
        метод показывает текст ошибки на экране вместо того, чтобы упасть.
        """
        if self._closed:
            return
        self._counter += 1

        fatal = None
        try:
            self.screen.update_from_display(self.display)
        except Exception as exc:
            fatal = exc
            try:
                self.screen.set_text("ОШИБКА ЭКРАНА")
            except Exception:
                pass
        try:
            self.receipt.update_from_printer(self.printer)
        except Exception as exc:
            fatal = fatal or exc
        try:
            if fatal is not None:
                self.error_text = "display/printer: %s" % (fatal,)
            elif not getattr(self.display, "text", None):
                self.error_text = "нет объекта display"
            else:
                self.error_text = None
        except Exception:
            self.error_text = None
        try:
            self._update_status()
        except Exception:
            pass
        try:
            self.clock_var.set("цикл %d" % self._counter)
        except Exception:
            pass

    def _read_board_status(self):
        """Необязательный статус платы: ``status()`` -> dict либо ``status_text()``.

        Поддерживаются оба варианта, любые исключения и странные типы молча
        игнорируются (``main.py`` обещает только ``.display/.keyboard/.printer``).
        """
        board = self.board
        status = getattr(board, "status", None)
        if callable(status):
            try:
                value = status()
            except Exception:
                value = None
            if isinstance(value, dict):
                parts = []
                for key in ("source", "reason"):
                    item = value.get(key)
                    if item:
                        parts.append(str(item))
                if parts:
                    return " \u2022 ".join(parts)
            elif isinstance(value, str) and value:
                return value
        text = getattr(board, "status_text", None)
        if callable(text):
            try:
                value = text()
            except Exception:
                value = None
            if isinstance(value, dict):
                parts = [str(value[k]) for k in ("source", "reason") if value.get(k)]
                if parts:
                    return " \u2022 ".join(parts)
            elif value:
                return str(value)
        return None

    def _update_status(self, force: bool = False) -> None:
        parts = []
        mode = self._read_board_status()
        if mode:
            parts.append(mode)
        if getattr(self, "error_text", None):
            parts.append("\u041e\u0428\u0418\u0411\u041a\u0410: %s" % self.error_text)
        parts.append("клавиш: %d" % len(getattr(self.keypad, "buttons", {}) or {}))
        if self._last_key:
            parts.append("последняя: %s" % self._last_key)
        printer_state = "\u0433\u043e\u0442\u043e\u0432"
        if self.printer is not None:
            try:
                printer_state = "\u0437\u0430\u043d\u044f\u0442" if self.printer.is_busy() else "\u0433\u043e\u0442\u043e\u0432"
            except Exception:
                printer_state = "\u043d/\u0434"
        parts.append("\u043f\u0440\u0438\u043d\u0442\u0435\u0440: %s" % printer_state)
        parts.append(
            "\u044d\u043a\u0440\u0430\u043d: %d x %d" % (self.screen.columns, self.screen.lines)
        )
        status = "   \u2022   ".join(parts)
        if force or status != self._last_status:
            self._last_status = status
